/* CHIP1 — SHARED PER-STRIP KERNELS (DSP4_SHARED_KERNELS) */
/* AUTO-GENERATED by tools/dsp/dsp_codegen.py — do not edit directly. */
/*
 * ONE body per class, entered per strip with that strip's record
 * base in a DAG register. The bodies here are the SAME emitters'
 * output as the inline arm in the node files -- generated from one
 * node and rewritten from absolute per-node addresses to record
 * offsets -- so the two arms cannot drift apart.
 *
 * The record layout is checked against the linker map after the
 * build by tools/dsp/shared_kernel_check.py. Do not assume it.
 */
#include "dsp_block.h"
#include "lib/dyn_lut.h"
#include "blk_pool.h"

#if !DSP4_BLOCK_KERNELS && DSP4_SHARED_KERNELS
#error "DSP4_SHARED_KERNELS needs DSP4_BLOCK_KERNELS: the stub stands where a per-block kernel call already was."
#endif

/* ==== COMP: one body for 32 strips ====
 * rewritten sites: 46 direct accesses, 4 DAG base loads, 4 address-to-register,
 * 2 predecessor-buffer accesses. */
#if (DSP4_SHARED_KERNELS & 1)
#define SHK_COMP_OFF_comp_on         (0)
#define SHK_COMP_OFF_comp_threshold  (SHK_COMP_OFF_comp_on + 1)
#define SHK_COMP_OFF_comp_ratio      (SHK_COMP_OFF_comp_threshold + 1)
#define SHK_COMP_OFF_comp_attack     (SHK_COMP_OFF_comp_ratio + 1)
#define SHK_COMP_OFF_comp_release    (SHK_COMP_OFF_comp_attack + 1)
#define SHK_COMP_OFF_comp_makeup     (SHK_COMP_OFF_comp_release + 1)
#define SHK_COMP_OFF_comp_makeup_target (SHK_COMP_OFF_comp_makeup + 1)
#define SHK_COMP_OFF_comp_makeup_step (SHK_COMP_OFF_comp_makeup_target + 1)
#define SHK_COMP_OFF_comp_makeup_frames (SHK_COMP_OFF_comp_makeup_step + 1)
#define SHK_COMP_OFF_comp_knee       (SHK_COMP_OFF_comp_makeup_frames + 1)
#define SHK_COMP_OFF_comp_parallel   (SHK_COMP_OFF_comp_knee + 1)
#define SHK_COMP_OFF_comp_type       (SHK_COMP_OFF_comp_parallel + 1)
#define SHK_COMP_OFF_comp_key_src    (SHK_COMP_OFF_comp_type + 1)
#define SHK_COMP_OFF_comp_det_src    (SHK_COMP_OFF_comp_key_src + 1)
#define SHK_COMP_OFF_comp_eq_pos     (SHK_COMP_OFF_comp_det_src + 1)
#define SHK_COMP_OFF_comp_lim_mode   (SHK_COMP_OFF_comp_eq_pos + 1)
#define SHK_COMP_OFF_comp_filter_on  (SHK_COMP_OFF_comp_lim_mode + 1)
#define SHK_COMP_OFF_comp_filter_coeffs (SHK_COMP_OFF_comp_filter_on + 1)
#define SHK_COMP_OFF_comp_filter_state (SHK_COMP_OFF_comp_filter_coeffs + 10)
#define SHK_COMP_OFF_comp_envelope   (SHK_COMP_OFF_comp_filter_state + 4)
#define SHK_COMP_OFF_comp_gain       (SHK_COMP_OFF_comp_envelope + 1)
#define SHK_COMP_OFF_comp_attq       (SHK_COMP_OFF_comp_gain + 1)
#define SHK_COMP_OFF_comp_relq       (SHK_COMP_OFF_comp_attq + 1)
#define SHK_COMP_OFF_comp_mkq        (SHK_COMP_OFF_comp_relq + 1)
#define SHK_COMP_OFF_comp_parq       (SHK_COMP_OFF_comp_mkq + 1)
#define SHK_COMP_OFF_comp_cgp        (SHK_COMP_OFF_comp_parq + 1)
#if DSP4_DYN_LUT
#define SHK_COMP_OFF_comp_lut        (SHK_COMP_OFF_comp_cgp + 4)
#define SHK_COMP_OFF_comp_lutc       (SHK_COMP_OFF_comp_lut + DYN_LUT_N)
#define SHK_COMP_OFF_comp_lutk       (SHK_COMP_OFF_comp_lutc + 1)
#define SHK_COMP_CUR0 (SHK_COMP_OFF_comp_lutk + 4)
#else
#define SHK_COMP_CUR0 (SHK_COMP_OFF_comp_cgp + 4)
#endif
#define SHK_COMP_OFF_buf             (SHK_COMP_CUR0)
#if DSP4_BLOCK_KERNELS
#define SHK_COMP_OFF_comp_saved_idx  (SHK_COMP_OFF_buf + 1)
#define SHK_COMP_CUR1 (SHK_COMP_OFF_comp_saved_idx + 1)
#else
#define SHK_COMP_CUR1 (SHK_COMP_OFF_buf + 1)
#endif
#define SHK_COMP_REC_LEN             (SHK_COMP_CUR1)

.section/pm seg_pmco;
        .extern _sample_idx;
        .extern _envq_fx;
        .extern _compgain_fx;
        .extern _mrf_rns28;
#if DSP4_DYN_LUT
        .extern _dyn_lut_step;
        .extern _dyn_lut_gain;
#endif
        .global _shk_comp_blk;
        _shk_comp_blk:

        #if DSP4_BLOCK_KERNELS
            /* ---- per-block kernel ----
             * Sample 0 goes through the per-sample body with _sample_idx
             * forced to 0, which runs the block-rate makeup ramp and the
             * whole parameter conversion exactly as a per-sample build
             * would -- and avoids duplicating ninety lines of conversion
             * here. Samples 1..BLOCK-1 then run hoisted.
             *
             * THE LOOP COUNT IS DSP4_BLOCK_SIZE-1 AND IT USED TO BE A
             * LITERAL 31. That literal survived the block-size
             * parameterisation (2026-08-28) because it is the only loop
             * count in the generator that was written as a number rather
             * than derived, and nothing downstream could see it: at
             * BLOCK=8 the compressor ran 1+31 = 32 samples of an 8-sample
             * block, reading 32 words from BLK_CHAIN_A_P1 and writing 32 to
             * BLK_CHAIN_B_P1 -- three slots past the end of each, over
             * BLK_FDR_L_P1/R and BLK_TAP_TRIM_P1. It is what made COMP look
             * BLOCK-INVARIANT (13.5k cycles/block at both block sizes);
             * it was doing the same 32 samples of work either way.
             *
             * The earlier verdict that COMP was not worth converting came
             * from a bare WRAP, which measured 8 % SLOWER, and from a
             * reading that _compgain_fx "clobbers all but four registers".
             * CORRECTED 2026-08-24. An earlier note here claimed r6 also
             * survives, from a scan of _compgain_fx's OWN text. That scan
             * was not transitive: _compgain_fx calls _exp2q_fx, and the
             * polynomial _exp2q_fx reaches r6. Keeping attq in r6 meant
             * the attack alpha was destroyed after the first sample and
             * the envelope follower ran on garbage for the rest of the
             * block -- visible as a compressor output FROZEN from sample 1
             * while a correct build converged smoothly. It never showed in
             * the earlier verification because that ran on a silent bench,
             * where _compgain_fx returns unity before it ever reaches
             * exp2.
             *
             * The survivors across BOTH _envq_fx (r0, r2, r4, r5) and
             * _compgain_fx WITH ITS CALLEES (r0-r6, r8-r12) are r7, r13,
             * r14 and r15 -- which is exactly what the original note on
             * this page said before it was overridden. Four registers, so
             * the release alpha goes back to a DM load per sample. */

            r2 = dm(SHK_COMP_OFF_comp_on, i7);
            r2 = pass r2;
            if eq jump (pc, .ckb_copy_shkcomp);

            r5 = dm(_sample_idx);
            dm(SHK_COMP_OFF_comp_saved_idx, i7) = r5;
            r5 = 0;
            dm(_sample_idx) = r5;
            r0 = dm(i3, 1);
            dm(i5, 0) = r0;
            call _shk_comp_smp;
            r0 = dm(SHK_COMP_OFF_buf, i7);
            dm(i4, 1) = r0;
            r5 = 1;
            dm(_sample_idx) = r5;

            r7 = dm(SHK_COMP_OFF_comp_attq, i7);
            r14 = dm(SHK_COMP_OFF_comp_envelope, i7);
            r15 = dm(SHK_COMP_OFF_comp_mkq, i7);

            lcntr = DSP4_BLOCK_SIZE-1, do .ckb_lp_shkcomp until lce;
                r13 = dm(i3, 1);
                r0 = abs r13;
                r1 = r14;
                r2 = r7;                  /* attq */
                r3 = dm(SHK_COMP_OFF_comp_relq, i7);
                call _envq_fx;
                r14 = r0;
#if DSP4_DYN_LUT
                /* The SCALAR FALLBACK path, so the test is inside the
                 * loop rather than the loop being duplicated: this runs
                 * only when a pair could not be formed, and correctness
                 * there matters more than the branch. */
                r4 = dm(SHK_COMP_OFF_comp_lutc, i7);
                r5 = DYN_LUT_N;
                comp(r4, r5);
                if lt jump (pc, .ckblutp_shkcomp);
                i0 = i7;
            modify(i0, SHK_COMP_OFF_comp_lut);
                call _dyn_lut_gain;
                jump (pc, .ckblutg_shkcomp);
            .ckblutp_shkcomp:
#endif
                i0 = i7;
            modify(i0, SHK_COMP_OFF_comp_cgp);
                call _compgain_fx;
#if DSP4_DYN_LUT
            .ckblutg_shkcomp:
#endif
                dm(SHK_COMP_OFF_comp_gain, i7) = r0;
                r1 = r0;
                r0 = r13;
                mrf = r0 * r1 (ssi);
                call _mrf_rns28;
                r1 = r15;
                mrf = r0 * r1 (ssi);
                call _mrf_rns28;
                r5 = r0 - r13;
                r4 = dm(SHK_COMP_OFF_comp_parq, i7);
                mrf = r5 * r4 (ssi);
                r1 = 0x40000000;
                r12 = 1;
                mrf = mrf + r1 * r12 (ssi);
                r1 = mr0f;
                r12 = mr1f;
                r1 = lshift r1 by -31;
                r12 = lshift r12 by 1;
                r1 = r1 or r12;
                r0 = r13 + r1;
                nop;
                nop;
            .ckb_lp_shkcomp: dm(i4, 1) = r0;

            dm(SHK_COMP_OFF_comp_envelope, i7) = r14;
            r5 = dm(SHK_COMP_OFF_comp_saved_idx, i7);
            dm(_sample_idx) = r5;
            rts;

        .ckb_copy_shkcomp:
            lcntr = DSP4_BLOCK_SIZE, do .ckb_cp_shkcomp until lce;
                r0 = dm(i3, 1);
            .ckb_cp_shkcomp: dm(i4, 1) = r0;
            rts;

        .global _shk_comp_smp;
        _shk_comp_smp:
        #endif

            r0 = dm(i5, 0);
            r2 = dm(SHK_COMP_OFF_comp_on, i7);
            r3 = 0;
            comp(r2, r3);
            if eq jump (pc, .comp_bypass_shkcomp);
            r13 = r0;                     /* dry (r13-r15 lib-safe) */
        #if DSP4_COMP_NOCVT
            jump (pc, .comp_go_shkcomp);   /* TEMP bisect: skip block-rate cvt */
        #endif

            /* --- block rate: makeup ramp + param conversion --- */
        /* Kept in BOTH builds: this node has a block kernel that drives
         * _sample_idx before reaching here, so the guard fires exactly
         * once per block and is doing its job. */
            r4 = dm(_sample_idx);
            r1 = 0;
            comp(r4, r1);
            if ne jump (pc, .comp_go_shkcomp);

            r4 = dm(SHK_COMP_OFF_comp_makeup_frames, i7);
            comp(r4, r1);
            if le jump (pc, .no_mramp_shkcomp);
            /* Consume a BLOCK's worth of frames and apply a BLOCK's
             * worth of step. spi_handler scales every profile frame count
             * by DSP4_BLOCK_SIZE, which is right for the ramps that
             * decrement once per SAMPLE. This one decrements once per
             * BLOCK, so taking 1 per block ran it BLOCK times long:
             * measured 2026-08-23 at BLOCK=32, a GainSafe down-ramp took
             * 960 ms against the 30 ms its own cell table specifies, and a
             * GainFast fader move took 85 ms instead of 3 ms. A power of
             * two is exact in binary, so scaling the step loses nothing. */
            r5 = DSP4_BLOCK_SIZE;
            r4 = r4 - r5;
            dm(SHK_COMP_OFF_comp_makeup_frames, i7) = r4;
            f1 = dm(SHK_COMP_OFF_comp_makeup, i7);
            f2 = dm(SHK_COMP_OFF_comp_makeup_step, i7);
            r5 = DSP4_BLOCK_F32;              /* BLOCK_SIZE as float */
            f5 = r5;
            f2 = f2 * f5;
            f1 = f1 + f2;
            dm(SHK_COMP_OFF_comp_makeup, i7) = f1;
            jump (pc, .comp_cvt_shkcomp);
        .no_mramp_shkcomp:
            f1 = dm(SHK_COMP_OFF_comp_makeup_target, i7);
            dm(SHK_COMP_OFF_comp_makeup, i7) = f1;
        .comp_cvt_shkcomp:
            r2 = 0x4D800000;
            f2 = r2;
            f1 = f1 * f2;
            r1 = fix f1;
            dm(SHK_COMP_OFF_comp_mkq, i7) = r1;
            /* PARALLEL BLEND IS PERCENT ON THE WIRE (review finding
             * D40). The master documents Chan[1-32]CompPar as 0-100 %
             * (d32-mx-master.csv, table 0=0/127=100); this used to
             * multiply the raw wire value by 2^31 with no /100, so any
             * documented value of 1 % or more pinned the blend fully wet
             * and the control could not take an intermediate setting at
             * all. The masters win: clamp to the documented 0..100 and
             * scale by 2^31/100. */
            f1 = dm(SHK_COMP_OFF_comp_parallel, i7);
            r2 = 0x00000000;              /* 0 %, documented minimum */
            f2 = r2;
            comp(f1, f2);
            if lt f1 = f2;
            r2 = 0x42C80000;              /* 100 %, documented maximum */
            f2 = r2;
            comp(f1, f2);
            if gt f1 = f2;
            r2 = 0x4BA3D70A;              /* 2^31 / 100 */
            f2 = r2;
            f1 = f1 * f2;
            r1 = fix f1;
            /* CLAMP. parallel = 100 % scales to exactly 2^31, which int32 cannot
             * hold: `fix` wraps and stores -1, so in Q0.31 the MAXIMUM
             * parallel setting blended in essentially nothing and the
             * compressor went fully DRY -- the same output as
             * parallel = 0, with a working compressor sitting behind it.
             * Bench 2026-08-23: par 0.999 settled at -16.49 dBFS on a
             * -6.02 dBFS step, par 1.0 returned the input untouched. */
            r3 = 0;
            r2 = 0x7FFFFFFF;
            comp(r1, r3);
            if lt r1 = pass r2;
            dm(SHK_COMP_OFF_comp_parq, i7) = r1;
            r2 = 0x4F000000;              /* 2^31 float */
            f2 = r2;
            f1 = dm(SHK_COMP_OFF_comp_attack, i7);
            f1 = f1 * f2;
            r1 = fix f1;
            dm(SHK_COMP_OFF_comp_attq, i7) = r1;
            f1 = dm(SHK_COMP_OFF_comp_release, i7);
            f1 = f1 * f2;
            r1 = fix f1;
            dm(SHK_COMP_OFF_comp_relq, i7) = r1;
            r2 = 0x4AAA152D;            /* dB -> Q6.25 log2 */
            f2 = r2;
            f1 = dm(SHK_COMP_OFF_comp_threshold, i7);
            f1 = f1 * f2;
            r1 = fix f1;
            dm(SHK_COMP_OFF_comp_cgp, i7) = r1;    /* thr */
            /* slope = 1 - 1/ratio */
            f6 = dm(SHK_COMP_OFF_comp_ratio, i7);
            f7 = recips f6;
            f8 = f6 * f7;
            r10 = 0x40000000;
            f8 = f10 - f8;
            f7 = f7 * f8;
            f8 = f6 * f7;
            f8 = f10 - f8;
            f6 = f7 * f8;
            r2 = 0x3F800000;
            f5 = r2;
            f5 = f5 - f6;                 /* slope float */
            r2 = 0x4F000000;
            f2 = r2;
            f1 = f5 * f2;
            r1 = fix f1;
            dm(SHK_COMP_OFF_comp_cgp + 1, i7) = r1;
            /* knee: halfk = knee_db/2 in Q6.25 log2; k2 = slope*K/(2*knee) Q6.25 */
            f4 = dm(SHK_COMP_OFF_comp_knee, i7);
            r2 = 0x3DCCCCCD;              /* 0.1 dB min for soft path */
            f3 = r2;
            comp(f4, f3);
            if gt jump (pc, .comp_soft_shkcomp);
            r1 = 0;
            dm(SHK_COMP_OFF_comp_cgp + 2, i7) = r1;
            dm(SHK_COMP_OFF_comp_cgp + 3, i7) = r1;
            jump (pc, .comp_kdone_shkcomp);
        .comp_soft_shkcomp:
            r2 = 0x4AAA152D;
            f2 = r2;
            f1 = f4 * f2;
            r2 = 0x3F000000;              /* 0.5 */
            f3 = r2;
            f1 = f1 * f3;
            r1 = fix f1;
            dm(SHK_COMP_OFF_comp_cgp + 2, i7) = r1;  /* halfk */
            f7 = recips f4;
            f8 = f4 * f7;
            r10 = 0x40000000;
            f8 = f10 - f8;
            f7 = f7 * f8;
            f8 = f4 * f7;
            f8 = f10 - f8;
            f6 = f7 * f8;
            r2 = 0x4040A8C1;             /* K/2 */
            f3 = r2;
            f6 = f6 * f3;                 /* K/(2*knee_db) */
            f6 = f6 * f5;                 /* * slope */
            r2 = 0x4C000000;              /* 2^25 float */
            f2 = r2;
            f1 = f6 * f2;
            r1 = fix f1;
            dm(SHK_COMP_OFF_comp_cgp + 3, i7) = r1;  /* k2 */
        .comp_kdone_shkcomp:
#if DSP4_DYN_LUT
            /* --- block rate: THE DESIGN STEP (S15) ---
             *
             * The four converted words in _comp_cgp_ ARE the curve. If
             * they have moved since the table was designed, the design
             * restarts; either way DYN_LUT_CHUNK points are filled per
             * block until the cursor reaches the end, and until it does
             * the per-sample body below runs the exact polynomial.
             *
             * WHY NOT ALL AT ONCE: one point is a whole _compgain_fx,
             * about 211 instructions, so a 337-point table is ~71,000
             * cycles against a block's 327,680 -- 22 % of a block for
             * ONE node, and chip 1 has 32 of them.
             *
             * WHY NOT A TWO-TABLE BLEND, which is what S14 proposed for
             * a ramping parameter: tools/dsp/dyn_lut_design.py --blend
             * measures it at 1.13 dB for a 10 dB threshold ramp and
             * 20.2 dB for a 57 dB one, against a 0.1 dB bar, because two
             * curves whose KNEES sit at different levels do not
             * interpolate into the curve whose knee is between them.
             * Running the polynomial while the table is stale is exact,
             * costs only what ships today, and needs no second table.
             *
             * r13 holds the live sample and both _dyn_lut_fill and
             * _compgain_fx under it clobber r0-r12 only. */
            r11 = i7;
            r0 = SHK_COMP_OFF_comp_cgp;
            r0 = r0 + r11;
            r11 = i7;
            r1 = SHK_COMP_OFF_comp_lutk;
            r1 = r1 + r11;
            r11 = i7;
            r2 = SHK_COMP_OFF_comp_lut;
            r2 = r2 + r11;
            r11 = i7;
            r3 = SHK_COMP_OFF_comp_lutc;
            r3 = r3 + r11;
            call _dyn_lut_step;
#endif
        .comp_go_shkcomp:

            /* --- envelope (fixed) --- */
            r0 = abs r13;
            r1 = dm(SHK_COMP_OFF_comp_envelope, i7);
            r2 = dm(SHK_COMP_OFF_comp_attq, i7);
            r3 = dm(SHK_COMP_OFF_comp_relq, i7);
            call _envq_fx;
            dm(SHK_COMP_OFF_comp_envelope, i7) = r0;

            /* --- gain computer --- */
#if DSP4_DYN_LUT
            /* ONE TABLE, level -> gain: no log2, no knee, no exp2. The
             * envelope is already in r0. A table that is still being
             * designed falls through to the polynomial, which is the
             * arithmetic the table is designed against, so the changeover
             * is a step of at most the table's own error (0.0950 dB worst
             * case over the documented parameter sweep, 0.004 dB at the
             * shipped defaults) at one block boundary. */
            r4 = dm(SHK_COMP_OFF_comp_lutc, i7);
            r5 = DYN_LUT_N;
            comp(r4, r5);
            if lt jump (pc, .clutpoly_shkcomp);
            i0 = i7;
            modify(i0, SHK_COMP_OFF_comp_lut);
            call _dyn_lut_gain;           /* r0 = gain Q4.28 */
            jump (pc, .clutgain_shkcomp);
        .clutpoly_shkcomp:
#endif
            i0 = i7;
            modify(i0, SHK_COMP_OFF_comp_cgp);
            call _compgain_fx;            /* r0 = gain Q4.28 */
#if DSP4_DYN_LUT
        .clutgain_shkcomp:
#endif
            dm(SHK_COMP_OFF_comp_gain, i7) = r0;

            /* wet = dry * gain * makeup */
            r1 = r0;
            r0 = r13;
            mrf = r0 * r1 (ssi);
            call _mrf_rns28;
            r1 = dm(SHK_COMP_OFF_comp_mkq, i7);
            mrf = r0 * r1 (ssi);
            call _mrf_rns28;

            /* parallel: out = dry + par*(wet - dry) — matches the float
             * node exactly (par==0 -> dry, its default behaviour) */
            r5 = r0 - r13;
            r4 = dm(SHK_COMP_OFF_comp_parq, i7);
            mrf = r5 * r4 (ssi);
            r1 = 0x40000000;
            r12 = 1;
            mrf = mrf + r1 * r12 (ssi);
            r1 = mr0f;
            r12 = mr1f;
            r1 = lshift r1 by -31;
            r12 = lshift r12 by 1;
            r1 = r1 or r12;
            r0 = r13 + r1;
            dm(SHK_COMP_OFF_buf, i7) = r0;
            rts;
        .comp_bypass_shkcomp:
            dm(SHK_COMP_OFF_buf, i7) = r0;
            rts;
        _shk_comp_blk.end:
#endif

/* ==== FILT: one body for 32 strips ====
 * rewritten sites: 35 direct accesses, 34 DAG base loads, 5 address-to-register,
 * 3 predecessor-buffer accesses. */
#if (DSP4_SHARED_KERNELS & 8)
#if DSP4_BQ_FLOAT
#define SHK_FILT_OFF_filt_hpf_A      (0)
#define SHK_FILT_CUR0 (SHK_FILT_OFF_filt_hpf_A + 5)
#elif DSP4_BQ_GUARD
#define SHK_FILT_OFF_filt_hpf_A      (0)
#define SHK_FILT_CUR0 (SHK_FILT_OFF_filt_hpf_A + 5 + 1)
#else
#define SHK_FILT_OFF_filt_hpf_A      (0)
#define SHK_FILT_CUR0 (SHK_FILT_OFF_filt_hpf_A + 5)
#endif
#if DSP4_BQ_FLOAT
#define SHK_FILT_OFF_filt_lpf_A      (SHK_FILT_CUR0)
#define SHK_FILT_CUR1 (SHK_FILT_OFF_filt_lpf_A + 5)
#else
#define SHK_FILT_OFF_filt_lpf_A      (SHK_FILT_CUR0)
#define SHK_FILT_CUR1 (SHK_FILT_OFF_filt_lpf_A + 5)
#endif
#define SHK_FILT_OFF_filt_state_A    (SHK_FILT_CUR1)
#if DSP4_BQ_FLOAT
#define SHK_FILT_OFF_filt_hpf_B      (SHK_FILT_OFF_filt_state_A + 12)
#define SHK_FILT_CUR2 (SHK_FILT_OFF_filt_hpf_B + 5)
#elif DSP4_BQ_GUARD
#define SHK_FILT_OFF_filt_hpf_B      (SHK_FILT_OFF_filt_state_A + 12)
#define SHK_FILT_CUR2 (SHK_FILT_OFF_filt_hpf_B + 5 + 1)
#else
#define SHK_FILT_OFF_filt_hpf_B      (SHK_FILT_OFF_filt_state_A + 12)
#define SHK_FILT_CUR2 (SHK_FILT_OFF_filt_hpf_B + 5)
#endif
#if DSP4_BQ_FLOAT
#define SHK_FILT_OFF_filt_lpf_B      (SHK_FILT_CUR2)
#define SHK_FILT_CUR3 (SHK_FILT_OFF_filt_lpf_B + 5)
#else
#define SHK_FILT_OFF_filt_lpf_B      (SHK_FILT_CUR2)
#define SHK_FILT_CUR3 (SHK_FILT_OFF_filt_lpf_B + 5)
#endif
#define SHK_FILT_OFF_filt_state_B    (SHK_FILT_CUR3)
#if DSP4_BQ_FLOAT
#define SHK_FILT_OFF_hpf_coeffs_next (SHK_FILT_OFF_filt_state_B + 12)
#define SHK_FILT_CUR4 (SHK_FILT_OFF_hpf_coeffs_next + 5)
#else
#define SHK_FILT_OFF_hpf_coeffs_next (SHK_FILT_OFF_filt_state_B + 12)
#define SHK_FILT_CUR4 (SHK_FILT_OFF_hpf_coeffs_next + 5)
#endif
#define SHK_FILT_OFF_hpf_swap_pending (SHK_FILT_CUR4)
#if DSP4_BQ_FLOAT
#define SHK_FILT_OFF_lpf_coeffs_next (SHK_FILT_OFF_hpf_swap_pending + 1)
#define SHK_FILT_CUR5 (SHK_FILT_OFF_lpf_coeffs_next + 5)
#else
#define SHK_FILT_OFF_lpf_coeffs_next (SHK_FILT_OFF_hpf_swap_pending + 1)
#define SHK_FILT_CUR5 (SHK_FILT_OFF_lpf_coeffs_next + 5)
#endif
#define SHK_FILT_OFF_lpf_swap_pending (SHK_FILT_CUR5)
#define SHK_FILT_OFF_filt_active     (SHK_FILT_OFF_lpf_swap_pending + 1)
#define SHK_FILT_OFF_filt_xfade_alpha (SHK_FILT_OFF_filt_active + 1)
#define SHK_FILT_OFF_filt_xfade_step (SHK_FILT_OFF_filt_xfade_alpha + 1)
#if DSP4_BQ_GUARD
#define SHK_FILT_OFF_filt_hrw        (SHK_FILT_OFF_filt_xfade_step + 1)
#define SHK_FILT_OFF_filt_hrl        (SHK_FILT_OFF_filt_hrw + 1)
#define SHK_FILT_CUR6 (SHK_FILT_OFF_filt_hrl + 2)
#else
#define SHK_FILT_CUR6 (SHK_FILT_OFF_filt_xfade_step + 1)
#endif
#define SHK_FILT_OFF_buf             (SHK_FILT_CUR6)
#define SHK_FILT_REC_LEN             (SHK_FILT_OFF_buf + 1)

.section/pm seg_pmco;
.extern _bq_fx_cascade_N;
.extern _bq_fx_convert_N;
#if DSP4_BLOCK_KERNELS
.extern _bq_fx_cascade_blk;
#endif
#if DSP4_BQ_GUARD
.extern _bq_hr_node1;
#endif
.global _shk_filt_blk;
_shk_filt_blk:

#if DSP4_BLOCK_KERNELS
    /* ---- per-block steady state; transients go per-sample ---- */
    r4 = dm(SHK_FILT_OFF_hpf_swap_pending, i7);
    r5 = dm(SHK_FILT_OFF_lpf_swap_pending, i7);
    r4 = r4 or r5;
    r5 = dm(SHK_FILT_OFF_filt_xfade_step, i7);
    r4 = r4 or r5;
#if DSP4_BQ_GUARD
    r5 = dm(SHK_FILT_OFF_filt_hrw, i7);
    r4 = r4 or r5;      /* a sizing in flight is a transient too */
#endif
    r4 = pass r4;
    if eq jump (pc, .fkb_ss_shkfilt);

    /* A swap is pending or a crossfade is running: run the block
     * through the per-sample reference path, one sample at a time,
     * staging through the scalar buffers it already uses.
     *
     * IN PLACE ON BLK_CHAIN_B_P1 (review finding D55, 2026-08-29).
     * This wrote BLK_CHAIN_A_P1 until today, which EQ's transient path
     * then read -- correct only when BOTH were crossfading. With
     * EQ steady, EQ cascaded the stale contents of B and this
     * node's output was dropped on the floor for the 576 samples of
     * the fade. The read and the write walk together, so sample i
     * is consumed before it is overwritten. */
    lcntr = DSP4_BLOCK_SIZE, do .fkb_xl_shkfilt until lce;
        r0 = dm(i3, 1);
        dm(i5, 0) = r0;
        call _shk_filt_smp;
        r0 = dm(SHK_FILT_OFF_buf, i7);
    .fkb_xl_shkfilt: dm(i4, 1) = r0;
    rts;

.fkb_ss_shkfilt:
    /* Steady state, FUSED. The cascade works IN PLACE, so FILT
     * filters its INPUT slot where it stands instead of copying the
     * block to the other half of the ping-pong first. EQ then
     * cascades in place on the same slot, so the FILT->EQ handoff
     * costs nothing at all: no copy, no slot change, no call
     * between them beyond the cascade itself. Two block copies
     * deleted, 4 memory ops per sample. */
    l0 = 0;
    l1 = 0;
    l2 = 0;
    l3 = 0;
    l4 = 0;

    r4 = dm(SHK_FILT_OFF_filt_active, i7);
    r4 = pass r4;
    if ne jump (pc, .fkb_b_shkfilt);
    i0 = i7;
            modify(i0, SHK_FILT_OFF_filt_hpf_A);
    i1 = i7;
            modify(i1, SHK_FILT_OFF_filt_state_A);
    i2 = i6;
    r4 = 2;                     /* HPF and LPF in ONE call: their
                                 * coefficient arrays are adjacent
                                 * and the state array is 2x6, so
                                 * the cascade walks both. */
    call _bq_fx_cascade_blk;
    rts;
.fkb_b_shkfilt:
    i0 = i7;
            modify(i0, SHK_FILT_OFF_filt_hpf_B);
    i1 = i7;
            modify(i1, SHK_FILT_OFF_filt_state_B);
    i2 = i6;
    r4 = 2;
    call _bq_fx_cascade_blk;
    rts;

.global _shk_filt_smp;
_shk_filt_smp:
#endif


    r4 = dm(SHK_FILT_OFF_hpf_swap_pending, i7);
    r5 = dm(SHK_FILT_OFF_lpf_swap_pending, i7);
    r4 = r4 or r5;
    #if DSP4_BQ_GUARD
    r6 = dm(SHK_FILT_OFF_filt_hrw, i7);
    r4 = r4 or r6;
    #endif
    r4 = pass r4;
    if ne call _shk_filt_start_xfade;

    r4 = dm(SHK_FILT_OFF_filt_xfade_step, i7);
    r4 = pass r4;
    if ne jump (pc, .filt_xfade_shkfilt);

    /* ===== steady state ===== */
    r0 = dm(i5, 0);
    r4 = dm(SHK_FILT_OFF_filt_active, i7);
    r4 = pass r4;
    if ne jump (pc, .filt_ss_b_shkfilt);
    i0 = i7;
            modify(i0, SHK_FILT_OFF_filt_hpf_A);
    i1 = i7;
            modify(i1, SHK_FILT_OFF_filt_state_A);
#if DSP4_BQ_GUARD
    /* HPF and LPF in ONE call, which is what the block kernel has
     * always done: the two coefficient arrays are adjacent and the
     * state is 2 x 6. Under the guard it is not an optimisation
     * but a requirement -- the headroom is a property of the
     * CASCADE, and this is where the cascade begins and ends. */
    r4 = 2;
    call _bq_fx_cascade_N;
#else
    r4 = 1;
    call _bq_fx_cascade_N;
    i0 = i7;
            modify(i0, SHK_FILT_OFF_filt_lpf_A);
    r4 = 1;
    call _bq_fx_cascade_N;      /* i1 continued to LPF state */
#endif
    dm(SHK_FILT_OFF_buf, i7) = r0;
    rts;
.filt_ss_b_shkfilt:
    i0 = i7;
            modify(i0, SHK_FILT_OFF_filt_hpf_B);
    i1 = i7;
            modify(i1, SHK_FILT_OFF_filt_state_B);
#if DSP4_BQ_GUARD
    r4 = 2;
    call _bq_fx_cascade_N;
#else
    r4 = 1;
    call _bq_fx_cascade_N;
    i0 = i7;
            modify(i0, SHK_FILT_OFF_filt_lpf_B);
    r4 = 1;
    call _bq_fx_cascade_N;
#endif
    dm(SHK_FILT_OFF_buf, i7) = r0;
    rts;

    /* ===== crossfade ===== */
.filt_xfade_shkfilt:
    r0 = dm(i5, 0);
    r13 = r0;
    i0 = i7;
            modify(i0, SHK_FILT_OFF_filt_hpf_A);
    i1 = i7;
            modify(i1, SHK_FILT_OFF_filt_state_A);
#if DSP4_BQ_GUARD
    r4 = 2;
    call _bq_fx_cascade_N;
#else
    r4 = 1;
    call _bq_fx_cascade_N;
    i0 = i7;
            modify(i0, SHK_FILT_OFF_filt_lpf_A);
    r4 = 1;
    call _bq_fx_cascade_N;
#endif
    r14 = r0;                     /* ya */
    r0 = r13;
    i0 = i7;
            modify(i0, SHK_FILT_OFF_filt_hpf_B);
    i1 = i7;
            modify(i1, SHK_FILT_OFF_filt_state_B);
#if DSP4_BQ_GUARD
    r4 = 2;
    call _bq_fx_cascade_N;        /* r0 = yb */
#else
    r4 = 1;
    call _bq_fx_cascade_N;
    i0 = i7;
            modify(i0, SHK_FILT_OFF_filt_lpf_B);
    r4 = 1;
    call _bq_fx_cascade_N;        /* r0 = yb */
#endif

    r4 = dm(SHK_FILT_OFF_filt_active, i7);
    r4 = pass r4;
    if eq jump (pc, .filt_bl_shkfilt);
    r5 = r14;
    r14 = r0;
    r0 = r5;
.filt_bl_shkfilt:
    f4 = dm(SHK_FILT_OFF_filt_xfade_alpha, i7);
    r5 = 0x4F000000;               /* 2^31 as float */
    f5 = r5;
    f4 = f4 * f5;
    r4 = fix f4;                   /* alpha_q31; see below */
    /* `fix` ROUNDS TO NEAREST, TIES TO EVEN, and it WRAPS -- it
     * does not saturate, and this comment said it did until the
     * S26 sweep (S25-2). Both halves matter here and neither
     * changes a word of the emitted code:
     *
     * ROUNDING. alpha is k/576 and the product alpha*2^31 is an
     * exact integer for every k except 1 and 2, whose fractions
     * are .25 and .5-with-an-even-integer-part; ties-to-even and
     * truncation agree on both. So the ramp NEVER separates the
     * two rules -- which is exactly why the wrong belief lived
     * here for months, and why the model was corrected against
     * the rule rather than against a failing vector.
     *
     * WRAPPING. alpha == 1.0 makes the product exactly 2^31,
     * which is not a 32-bit integer; the part returns 0xFFFFFFFF
     * for it, not a saturated 0x7FFFFFFF (the same wrap the
     * compressor's parallel-blend clamp exists to dodge, bench
     * 2026-08-23). The corner is UNREACHABLE because the ramp
     * stores alpha only while it is still below 1.0 -- but the
     * safety is the ramp's, not this instruction's, so any
     * change to the ramp has to preserve alpha < 1.0.
     *
     * alpha*(new - old) as TWO MACs into the 80-bit MRF, so the
     * difference is NEVER formed in a 32-bit register (review
     * finding D3). `new` and `old` are independently saturated
     * Q4.28 outputs, so new-old spans +/-(2^32-1) and the old
     * `r5 = r0 - r14` wrapped when the two instances straddled
     * full scale mid-swap -- up to a block of full-scale-wrong
     * samples, a click. Same instruction count, and identical
     * arithmetic everywhere the subtract did not wrap.
     * Model: fixed_ref.xfade_blend. The final add cannot
     * overflow -- the result is a convex combination of two
     * int32s, bounded by them; the bound is in numeric-spec.md.
     *
     * EMITTED FROM ONE PLACE: _xfade_blend_core() in
     * dsp_codegen.py. Every EQ/GEQ/AFB/FILT/CROSSOVER node and
     * the in-part self-test (lib/num_selftest.asm) get these
     * exact instructions from this one expression, so the
     * sequence the self-test proves bit-exact against the model
     * is the sequence the nodes run. */
    mrf = r0 * r4 (ssi);           /* + new*alpha */
    mrf = mrf - r14 * r4 (ssi);    /* - old*alpha */
    r5 = 0x40000000;               /* 2^30 rounding half */
    r12 = 1;
    mrf = mrf + r5 * r12 (ssi);
    r5 = mr0f;
    r12 = mr1f;
    r5 = lshift r5 by -31;
    r12 = lshift r12 by 1;
    r5 = r5 or r12;
    r0 = r14 + r5;                 /* blended output */
    dm(SHK_FILT_OFF_buf, i7) = r0;

    f4 = dm(SHK_FILT_OFF_filt_xfade_alpha, i7);
    f5 = dm(SHK_FILT_OFF_filt_xfade_step, i7);
    f4 = f4 + f5;
    dm(SHK_FILT_OFF_filt_xfade_alpha, i7) = f4;
    r5 = 0x3F800000;
    f5 = r5;
    comp(f4, f5);
    if lt rts;
    r4 = dm(SHK_FILT_OFF_filt_active, i7);
    r5 = 1;
    r4 = r4 xor r5;
    dm(SHK_FILT_OFF_filt_active, i7) = r4;
    r4 = 0;
    dm(SHK_FILT_OFF_filt_xfade_step, i7) = r4;
    dm(SHK_FILT_OFF_filt_xfade_alpha, i7) = r4;
    rts;

    /* ===== stage into dormant ===== */
_shk_filt_start_xfade:
#if DSP4_BQ_GUARD
    r4 = dm(SHK_FILT_OFF_filt_hrw, i7);
    r4 = pass r4;
    if ne jump (pc, .filt_hrp_shkfilt);   /* already converted */
#endif
    /* dormant pointers (i1 = coeff base, i2 = state base) and
     * active coeff base (i0) */
    r4 = dm(SHK_FILT_OFF_filt_active, i7);
    r4 = pass r4;
    if ne jump (pc, .filt_st_a_shkfilt);
    i0 = i7;
            modify(i0, SHK_FILT_OFF_filt_hpf_A);       /* active = A (hpf+lpf adjacent) */
    i1 = i7;
            modify(i1, SHK_FILT_OFF_filt_hpf_B);
    i2 = i7;
            modify(i2, SHK_FILT_OFF_filt_state_B);
    jump (pc, .filt_st_go_shkfilt);
.filt_st_a_shkfilt:
    i0 = i7;
            modify(i0, SHK_FILT_OFF_filt_hpf_B);
    i1 = i7;
            modify(i1, SHK_FILT_OFF_filt_hpf_A);
    i2 = i7;
            modify(i2, SHK_FILT_OFF_filt_state_A);
.filt_st_go_shkfilt:
    /* baseline: copy active fixed hpf[5] to dormant hpf. With the
     * guard the block carries a header word in front of it, and
     * the copy carries it too -- the sizer overwrites it a
     * millisecond later, but a stale H is never a wrong H here
     * because the coefficients it belonged to came with it. */
    r5 = 5 + DSP4_BQ_HDR;
    lcntr = r5, do .filt_cph_shkfilt until lce;
        r4 = dm(i0, 1);
.filt_cph_shkfilt:
        dm(i1, 1) = r4;
    /* i0/i1 now at the lpf blocks only if hpf/lpf are adjacent —
     * they are separate vars, so reload explicitly */
    r4 = dm(SHK_FILT_OFF_filt_active, i7);
    r4 = pass r4;
    if ne jump (pc, .filt_st2a_shkfilt);
    i0 = i7;
            modify(i0, SHK_FILT_OFF_filt_lpf_A);
    i1 = i7;
            modify(i1, SHK_FILT_OFF_filt_lpf_B);
    jump (pc, .filt_st2go_shkfilt);
.filt_st2a_shkfilt:
    i0 = i7;
            modify(i0, SHK_FILT_OFF_filt_lpf_B);
    i1 = i7;
            modify(i1, SHK_FILT_OFF_filt_lpf_A);
.filt_st2go_shkfilt:
    r5 = 5;
    lcntr = r5, do .filt_cpl_shkfilt until lce;
        r4 = dm(i0, 1);
.filt_cpl_shkfilt:
        dm(i1, 1) = r4;

    /* overwrite pending filter(s) from float staging */
    r4 = dm(SHK_FILT_OFF_hpf_swap_pending, i7);
    r4 = pass r4;
    if eq jump (pc, .filt_nohpf_shkfilt);
    r4 = 0;
    dm(SHK_FILT_OFF_hpf_swap_pending, i7) = r4;
    i0 = i7;
            modify(i0, SHK_FILT_OFF_hpf_coeffs_next);
    r4 = dm(SHK_FILT_OFF_filt_active, i7);
    r4 = pass r4;
    if ne jump (pc, .filt_cvha_shkfilt);
    i1 = i7;
            modify(i1, SHK_FILT_OFF_filt_hpf_B);
    jump (pc, .filt_cvhgo_shkfilt);
.filt_cvha_shkfilt:
    i1 = i7;
            modify(i1, SHK_FILT_OFF_filt_hpf_A);
.filt_cvhgo_shkfilt:
    #if DSP4_BQ_GUARD
l1 = 0;
modify(i1, 1);            /* past the headroom header */
#endif
    r4 = 1;
    call _bq_fx_convert_N;
.filt_nohpf_shkfilt:
    r4 = dm(SHK_FILT_OFF_lpf_swap_pending, i7);
    r4 = pass r4;
    if eq jump (pc, .filt_nolpf_shkfilt);
    r4 = 0;
    dm(SHK_FILT_OFF_lpf_swap_pending, i7) = r4;
    i0 = i7;
            modify(i0, SHK_FILT_OFF_lpf_coeffs_next);
    r4 = dm(SHK_FILT_OFF_filt_active, i7);
    r4 = pass r4;
    if ne jump (pc, .filt_cvla_shkfilt);
    i1 = i7;
            modify(i1, SHK_FILT_OFF_filt_lpf_B);
    jump (pc, .filt_cvlgo_shkfilt);
.filt_cvla_shkfilt:
    i1 = i7;
            modify(i1, SHK_FILT_OFF_filt_lpf_A);
.filt_cvlgo_shkfilt:
    r4 = 1;
    call _bq_fx_convert_N;
.filt_nolpf_shkfilt:
    #if DSP4_BQ_GUARD
    .filt_hrp_shkfilt:      /* re-entry: converted, still asking */
    r11 = i7;
            r0 = SHK_FILT_OFF_filt_hrw;
            r0 = r0 + r11;
    r11 = i7;
            r1 = SHK_FILT_OFF_filt_hrl;
            r1 = r1 + r11;
    r11 = i7;
            r2 = SHK_FILT_OFF_filt_active;
            r2 = r2 + r11;
    r11 = i7;
            r3 = SHK_FILT_OFF_filt_hpf_A;
            r3 = r3 + r11;
    r11 = i7;
            r4 = SHK_FILT_OFF_filt_hpf_B;
            r4 = r4 + r11;
    r5 = 2;
    call _bq_hr_ask;
    r0 = pass r0;
    if eq rts;              /* not sized yet; back next block */
    #endif

    /* zero dormant state + start ramp */
    r4 = dm(SHK_FILT_OFF_filt_active, i7);
    r4 = pass r4;
    if ne jump (pc, .filt_zsa_shkfilt);
    i2 = i7;
            modify(i2, SHK_FILT_OFF_filt_state_B);
    jump (pc, .filt_zsgo_shkfilt);
.filt_zsa_shkfilt:
    i2 = i7;
            modify(i2, SHK_FILT_OFF_filt_state_A);
.filt_zsgo_shkfilt:
    r4 = 0;
    r5 = 12;
    lcntr = r5, do .filt_zst_shkfilt until lce;
.filt_zst_shkfilt:
        dm(i2, 1) = r4;
    f0 = 0.001736111111111111;
    dm(SHK_FILT_OFF_filt_xfade_step, i7) = f0;
    r4 = 0;
    dm(SHK_FILT_OFF_filt_xfade_alpha, i7) = r4;
    rts;
_shk_filt_blk.end:
#endif

/* ==== GATE: one body for 32 strips ====
 * rewritten sites: 64 direct accesses, 5 DAG base loads, 0 address-to-register,
 * 2 predecessor-buffer accesses. */
#if (DSP4_SHARED_KERNELS & 4)
#define SHK_GATE_OFF_gate_on         (0)
#define SHK_GATE_OFF_gate_threshold  (SHK_GATE_OFF_gate_on + 1)
#define SHK_GATE_OFF_gate_attack     (SHK_GATE_OFF_gate_threshold + 1)
#define SHK_GATE_OFF_gate_release    (SHK_GATE_OFF_gate_attack + 1)
#define SHK_GATE_OFF_gate_hold       (SHK_GATE_OFF_gate_release + 1)
#if !DSP4_PAIRED_GRAPH
#define SHK_GATE_OFF_gate_hold_count (SHK_GATE_OFF_gate_hold + 1)
#define SHK_GATE_CUR0 (SHK_GATE_OFF_gate_hold_count + 1)
#else
#define SHK_GATE_CUR0 (SHK_GATE_OFF_gate_hold + 1)
#endif
#define SHK_GATE_OFF_gate_range      (SHK_GATE_CUR0)
#define SHK_GATE_OFF_gate_key_src    (SHK_GATE_OFF_gate_range + 1)
#define SHK_GATE_OFF_gate_det_src    (SHK_GATE_OFF_gate_key_src + 1)
#define SHK_GATE_OFF_gate_filter_on  (SHK_GATE_OFF_gate_det_src + 1)
#if DSP4_BQ_FLOAT
#define SHK_GATE_OFF_gate_filter_hpf (SHK_GATE_OFF_gate_filter_on + 1)
#define SHK_GATE_CUR1 (SHK_GATE_OFF_gate_filter_hpf + 5)
#else
#define SHK_GATE_OFF_gate_filter_hpf (SHK_GATE_OFF_gate_filter_on + 1)
#define SHK_GATE_CUR1 (SHK_GATE_OFF_gate_filter_hpf + 5)
#endif
#if DSP4_BQ_FLOAT
#define SHK_GATE_OFF_gate_filter_lpf (SHK_GATE_CUR1)
#define SHK_GATE_CUR2 (SHK_GATE_OFF_gate_filter_lpf + 5)
#else
#define SHK_GATE_OFF_gate_filter_lpf (SHK_GATE_CUR1)
#define SHK_GATE_CUR2 (SHK_GATE_OFF_gate_filter_lpf + 5)
#endif
#if DSP4_BQ_GUARD
#define SHK_GATE_OFF_gate_filter_cq  (SHK_GATE_CUR2)
#define SHK_GATE_CUR3 (SHK_GATE_OFF_gate_filter_cq + 11)
#else
#define SHK_GATE_OFF_gate_filter_cq  (SHK_GATE_CUR2)
#define SHK_GATE_CUR3 (SHK_GATE_OFF_gate_filter_cq + 10)
#endif
#define SHK_GATE_OFF_gate_filter_state (SHK_GATE_CUR3)
#define SHK_GATE_OFF_gate_envelope   (SHK_GATE_OFF_gate_filter_state + 12)
#define SHK_GATE_OFF_gate_gain       (SHK_GATE_OFF_gate_envelope + 1)
#define SHK_GATE_OFF_gate_gain_target_q (SHK_GATE_OFF_gate_gain + 1)
#if DSP4_PAIRED_GRAPH
#define SHK_GATE_OFF_gate_hold_count (SHK_GATE_OFF_gate_gain_target_q + 1)
#define SHK_GATE_CUR4 (SHK_GATE_OFF_gate_hold_count + 1)
#else
#define SHK_GATE_CUR4 (SHK_GATE_OFF_gate_gain_target_q + 1)
#endif
#define SHK_GATE_OFF_gate_attq       (SHK_GATE_CUR4)
#define SHK_GATE_OFF_gate_relq       (SHK_GATE_OFF_gate_attq + 1)
#define SHK_GATE_OFF_gate_thrq       (SHK_GATE_OFF_gate_relq + 1)
#define SHK_GATE_OFF_gate_rngq       (SHK_GATE_OFF_gate_thrq + 1)
#if DSP4_PAIRED_GRAPH
#define SHK_GATE_OFF_gate_holdq      (SHK_GATE_OFF_gate_rngq + 1)
#define SHK_GATE_CUR5 (SHK_GATE_OFF_gate_holdq + 1)
#else
#define SHK_GATE_CUR5 (SHK_GATE_OFF_gate_rngq + 1)
#endif
#define SHK_GATE_OFF_buf             (SHK_GATE_CUR5)
#if DSP4_BLOCK_KERNELS
#define SHK_GATE_OFF_gate_saved_idx  (SHK_GATE_OFF_buf + 1)
#define SHK_GATE_CUR6 (SHK_GATE_OFF_gate_saved_idx + 1)
#else
#define SHK_GATE_CUR6 (SHK_GATE_OFF_buf + 1)
#endif
#define SHK_GATE_REC_LEN             (SHK_GATE_CUR6)

.section/pm seg_pmco;
.extern _sample_idx;
.extern _envq_fx;
.extern _log2q_fx;
.extern _exp2q_fx;
.extern _mrf_rns28;
.extern _bq_fx_cascade_N;
.extern _bq_fx_convert_N;
.global _shk_gate_blk;
_shk_gate_blk:

#if DSP4_BLOCK_KERNELS
    /* ---- per-block kernel ----------------------------------
     * Hoisted out of the sample loop: the _sample_idx == 0 guard
     * (evaluated 32 times for work done once), the _gate_on and
     * _gate_filter_on tests, and the four converted parameters,
     * which are block constants but were re-loaded from DM every
     * sample. Envelope, gain, gain target and hold count stay in
     * registers across the block -- _envq_fx, _log2q_fx and
     * _mrf_rns28 all preserve r6-r15, which is what makes that
     * safe. The sidechain biquad does NOT (it clobbers r0-r12),
     * so a gate with its sidechain filter enabled falls back to
     * the per-sample path for the whole block.
     *
     * NOTE the guard cannot simply be kept: under block kernels
     * _sample_idx is 31 when the chain runs, so a _sample_idx == 0
     * test never fires and the parameters would never convert at
     * all. The conversion is done unconditionally, once. */

    r2 = dm(SHK_GATE_OFF_gate_on, i7);
    r2 = pass r2;
    if eq jump (pc, .gkb_copy_shkgate);
    r2 = dm(SHK_GATE_OFF_gate_filter_on, i7);
    r2 = pass r2;
    if ne jump (pc, .gkb_ref_shkgate);

    /* block-rate parameter conversion, once */
    r2 = 0x4F000000;
    f2 = r2;
    f1 = dm(SHK_GATE_OFF_gate_attack, i7);
    f1 = f1 * f2;
    r1 = fix f1;
    dm(SHK_GATE_OFF_gate_attq, i7) = r1;
    f1 = dm(SHK_GATE_OFF_gate_release, i7);
    f1 = f1 * f2;
    r1 = fix f1;
    dm(SHK_GATE_OFF_gate_relq, i7) = r1;
    r2 = 0x4AAA152D;
    f2 = r2;
    f1 = dm(SHK_GATE_OFF_gate_threshold, i7);
    f1 = f1 * f2;
    r1 = fix f1;
    dm(SHK_GATE_OFF_gate_thrq, i7) = r1;
    /* GATE RANGE IS DECIBELS ON THE WIRE (review finding D39).
     * The master documents Chan[1-32]GateRng as depth in dB
     * (d32-mx-master.csv, table 0=0/127=60, note "Gate
     * depth/range 0-60dB"). This used to scale the wire float
     * straight by 2^28 and use it as a LINEAR floor, so a host
     * writing the documented 40.0 got 40.0 x 2^28 -- saturated
     * garbage -- and the deepest gate the protocol can ask for
     * produced no attenuation at all. dsp_simulate.py:237 has
     * always performed this conversion, which is what proved the
     * convention was dB before it was ever measured.
     *
     * CELL SEMANTICS ARE THE CONTRACT AND THE MASTERS WIN, so the
     * conversion belongs here: floor = 10^(-dB/20), which is
     * 2^(-dB * log2(10)/20), clamped to the documented 0..60 dB.
     * It is BLOCK RATE -- this whole section sits behind the
     * _sample_idx == 0 guard -- and _exp2q_fx preserves r6-r15 in
     * both its table and polynomial forms, so the live sample in
     * r13 survives the call. */
    f1 = dm(SHK_GATE_OFF_gate_range, i7);
    r2 = 0x00000000;              /* 0 dB, documented minimum */
    f2 = r2;
    comp(f1, f2);
    if lt f1 = f2;
    r2 = 0x42700000;              /* 60 dB, documented maximum */
    f2 = r2;
    comp(f1, f2);
    if gt f1 = f2;
    r2 = 0xBE2A152D;              /* -log2(10)/20 */
    f2 = r2;
    f1 = f1 * f2;
    r2 = 0x4C000000;              /* x 2^25 -> Q6.25 for _exp2q_fx */
    f2 = r2;
    f1 = f1 * f2;
    r0 = fix f1;
    call _exp2q_fx;               /* r0 = 2^l, Q4.28 */
    dm(SHK_GATE_OFF_gate_rngq, i7) = r0;
#if DSP4_PAIRED_GRAPH
    r1 = dm(SHK_GATE_OFF_gate_hold, i7);
    dm(SHK_GATE_OFF_gate_holdq, i7) = r1;   /* five consecutive param words */
#endif

#if DSP4_GATE_LINTHR
    /* THRESHOLD IN THE LINEAR DOMAIN, ONCE PER BLOCK.
     *
     * GATE computes log2(env) for one purpose only: to compare it
     * against a threshold. That comparison is equivalent in the
     * linear domain -- log2(env) >= thr  <=>  env >= 2^thr -- so
     * the threshold is converted ONCE here instead of the envelope
     * being converted 32 times in the sample loop. It deletes a
     * _log2q_fx call per sample, measured at ~95 cycles/sample.
     *
     * NUMERIC DEVIATION, and it is a small one. Both directions go
     * through the same polynomials, whose worst error over 0 to
     * -100 dBFS is 0.0001 dB (log2_q) and 0.0001 dB (exp2_q), so
     * the gate's EFFECTIVE THRESHOLD shifts by at most 0.0002 dB.
     * That is a fixed offset on the threshold, not per-sample
     * noise, and the linear compare is exact where the log compare
     * carried the polynomial error. Samples whose envelope sits
     * within 0.0002 dB of the threshold may open or close one
     * sample earlier or later; the gain then ramps through a
     * one-pole smoother, so nothing steps.
     *
     * NOT bit-exact against the current fixed_ref, so it needs a
     * numeric-spec amendment and PW's sign-off before it ships.
     *
     * THIS CALL MUST COME BEFORE r6/r7 ARE LOADED. _exp2q_fx
     * clobbers r0-r6, so placing it after the attack/release
     * alphas were in r6/r7 destroyed the attack alpha and the
     * envelope follower ran on garbage -- measured as a 60 dB
     * difference, not the 0.0002 dB the arithmetic predicts. */
    r0 = dm(SHK_GATE_OFF_gate_thrq, i7);
    call _exp2q_fx;
    r8 = r0;                      /* 2^thr, Q4.28 linear */
    /* AND BACK INTO THE WORD, so that word means exactly one
     * thing under this switch whichever body ran (S15). It is
     * re-derived from the float parameter at the top of every
     * block, so converting in place cannot compound. */
    dm(SHK_GATE_OFF_gate_thrq, i7) = r0;
#else
    r8 = dm(SHK_GATE_OFF_gate_thrq, i7);
#endif
    r6 = dm(SHK_GATE_OFF_gate_attq, i7);
    r7 = dm(SHK_GATE_OFF_gate_relq, i7);

    r9 = dm(SHK_GATE_OFF_gate_rngq, i7);
    r10 = dm(SHK_GATE_OFF_gate_envelope, i7);
    r11 = dm(SHK_GATE_OFF_gate_gain, i7);
    r12 = dm(SHK_GATE_OFF_gate_gain_target_q, i7);
    r14 = dm(SHK_GATE_OFF_gate_hold_count, i7);
    r15 = dm(SHK_GATE_OFF_gate_hold, i7);

    lcntr = DSP4_BLOCK_SIZE, do .gkb_lp_shkgate until lce;
        r13 = dm(i3, 1);
        r0 = abs r13;
        r1 = r10;
        r2 = r6;
        r3 = r7;
        call _envq_fx;
        r10 = r0;
        r1 = pass r0;
        if le jump (pc, .gkb_below_shkgate);
#if DSP4_GATE_LINTHR
        comp(r0, r8);             /* env vs 2^thr, both Q4.28 */
#else
        call _log2q_fx;
        comp(r0, r8);
#endif
        if ge jump (pc, .gkb_open_shkgate);
    .gkb_below_shkgate:
        r14 = r14 - 1;
        if gt jump (pc, .gkb_ramp_shkgate);
        r12 = r9;
        jump (pc, .gkb_ramp_shkgate);
    .gkb_open_shkgate:
        r12 = 0x10000000;
        r14 = r15;
    .gkb_ramp_shkgate:
        r0 = r12;
        r1 = r11;
        r2 = r6;
        r3 = r7;
        call _envq_fx;
        r11 = r0;
        r1 = r0;
        r0 = r13;
        mrf = r0 * r1 (ssi);
        call _mrf_rns28;
        nop;
        nop;
    .gkb_lp_shkgate: dm(i4, 1) = r0;

    dm(SHK_GATE_OFF_gate_envelope, i7) = r10;
    dm(SHK_GATE_OFF_gate_gain, i7) = r11;
    dm(SHK_GATE_OFF_gate_gain_target_q, i7) = r12;
    dm(SHK_GATE_OFF_gate_hold_count, i7) = r14;
    rts;

.gkb_copy_shkgate:
    /* bypassed: the per-sample body just passes x through */
    lcntr = DSP4_BLOCK_SIZE, do .gkb_cp_shkgate until lce;
        r0 = dm(i3, 1);
    .gkb_cp_shkgate: dm(i4, 1) = r0;
    rts;

.gkb_ref_shkgate:
    /* Sidechain filter enabled: hand the block to the per-sample
     * reference path. _sample_idx is driven so its once-per-block
     * conversion fires on the first sample exactly as it would in
     * a per-sample build. */
    r5 = dm(_sample_idx);
    dm(SHK_GATE_OFF_gate_saved_idx, i7) = r5;
    r5 = 0;
    dm(_sample_idx) = r5;
    lcntr = DSP4_BLOCK_SIZE, do .gkb_rl_shkgate until lce;
        r0 = dm(i3, 1);
        dm(i5, 0) = r0;
        call _shk_gate_smp;
        r5 = 1;
        dm(_sample_idx) = r5;
        r0 = dm(SHK_GATE_OFF_buf, i7);
    .gkb_rl_shkgate: dm(i4, 1) = r0;
    r5 = dm(SHK_GATE_OFF_gate_saved_idx, i7);
    dm(_sample_idx) = r5;
    rts;

.global _shk_gate_smp;
_shk_gate_smp:
#endif

    r0 = dm(i5, 0);
    r2 = dm(SHK_GATE_OFF_gate_on, i7);
    r3 = 0;
    comp(r2, r3);
    if eq jump (pc, .gate_bypass_shkgate);
    r13 = r0;

    /* --- block rate: param conversion --- */
/* Kept in BOTH builds: this node has a block kernel that drives
 * _sample_idx before reaching here, so the guard fires exactly
 * once per block and is doing its job. */
    r4 = dm(_sample_idx);
    r1 = 0;
    comp(r4, r1);
    if ne jump (pc, .gate_go_shkgate);

    r2 = 0x4F000000;
    f2 = r2;
    f1 = dm(SHK_GATE_OFF_gate_attack, i7);
    f1 = f1 * f2;
    r1 = fix f1;
    dm(SHK_GATE_OFF_gate_attq, i7) = r1;
    f1 = dm(SHK_GATE_OFF_gate_release, i7);
    f1 = f1 * f2;
    r1 = fix f1;
    dm(SHK_GATE_OFF_gate_relq, i7) = r1;
    r2 = 0x4AAA152D;
    f2 = r2;
    f1 = dm(SHK_GATE_OFF_gate_threshold, i7);
    f1 = f1 * f2;
    r1 = fix f1;
    dm(SHK_GATE_OFF_gate_thrq, i7) = r1;
#if DSP4_GATE_LINTHR
    /* THE THRESHOLD IN THE LINEAR DOMAIN, ONCE PER BLOCK — and
     * the word itself carries the linear value, so no reader
     * can pick up the log one (S15).
     *
     * log2(env) >= thr is env >= 2^thr, so the conversion is
     * done here, once, instead of the envelope being converted
     * every sample. In the PAIRED graph this word is one of the
     * five _gate_pair_blk gathers, which is why the store
     * matters and not just the register.
     *
     * _exp2q_fx preserves r6-r15, so the live sample in r13
     * survives; r2 is dead here and the range conversion below
     * reloads it. */
    r0 = r1;
    call _exp2q_fx;               /* r0 = 2^thr, Q4.28 */
    dm(SHK_GATE_OFF_gate_thrq, i7) = r0;
#endif
    /* GATE RANGE IS DECIBELS ON THE WIRE (review finding D39).
     * The master documents Chan[1-32]GateRng as depth in dB
     * (d32-mx-master.csv, table 0=0/127=60, note "Gate
     * depth/range 0-60dB"). This used to scale the wire float
     * straight by 2^28 and use it as a LINEAR floor, so a host
     * writing the documented 40.0 got 40.0 x 2^28 -- saturated
     * garbage -- and the deepest gate the protocol can ask for
     * produced no attenuation at all. dsp_simulate.py:237 has
     * always performed this conversion, which is what proved the
     * convention was dB before it was ever measured.
     *
     * CELL SEMANTICS ARE THE CONTRACT AND THE MASTERS WIN, so the
     * conversion belongs here: floor = 10^(-dB/20), which is
     * 2^(-dB * log2(10)/20), clamped to the documented 0..60 dB.
     * It is BLOCK RATE -- this whole section sits behind the
     * _sample_idx == 0 guard -- and _exp2q_fx preserves r6-r15 in
     * both its table and polynomial forms, so the live sample in
     * r13 survives the call. */
    f1 = dm(SHK_GATE_OFF_gate_range, i7);
    r2 = 0x00000000;              /* 0 dB, documented minimum */
    f2 = r2;
    comp(f1, f2);
    if lt f1 = f2;
    r2 = 0x42700000;              /* 60 dB, documented maximum */
    f2 = r2;
    comp(f1, f2);
    if gt f1 = f2;
    r2 = 0xBE2A152D;              /* -log2(10)/20 */
    f2 = r2;
    f1 = f1 * f2;
    r2 = 0x4C000000;              /* x 2^25 -> Q6.25 for _exp2q_fx */
    f2 = r2;
    f1 = f1 * f2;
    r0 = fix f1;
    call _exp2q_fx;               /* r0 = 2^l, Q4.28 */
    dm(SHK_GATE_OFF_gate_rngq, i7) = r0;
#if DSP4_PAIRED_GRAPH
    r1 = dm(SHK_GATE_OFF_gate_hold, i7);
    dm(SHK_GATE_OFF_gate_holdq, i7) = r1;   /* five consecutive param words */
#endif
    r2 = dm(SHK_GATE_OFF_gate_filter_on, i7);
    r2 = pass r2;
    if eq jump (pc, .gate_go_shkgate);
    i0 = i7;
            modify(i0, SHK_GATE_OFF_gate_filter_hpf);
    i1 = i7;
            modify(i1, SHK_GATE_OFF_gate_filter_cq);
#if DSP4_BQ_GUARD
    l1 = 0;
    modify(i1, 1);            /* past the headroom header */
#endif
    r4 = 1;
    call _bq_fx_convert_N;
    i0 = i7;
            modify(i0, SHK_GATE_OFF_gate_filter_lpf);
    r4 = 1;
    call _bq_fx_convert_N;      /* i1 continued */
.gate_go_shkgate:

    /* --- sidechain: |x| (+ optional HPF/LPF) --- */
    r0 = abs r13;
    r2 = dm(SHK_GATE_OFF_gate_filter_on, i7);
    r2 = pass r2;
    if eq jump (pc, .gate_nofilt_shkgate);
    i0 = i7;
            modify(i0, SHK_GATE_OFF_gate_filter_cq);
    i1 = i7;
            modify(i1, SHK_GATE_OFF_gate_filter_state);
    r4 = 2;
    call _bq_fx_cascade_N;
    r0 = abs r0;
.gate_nofilt_shkgate:

    r1 = dm(SHK_GATE_OFF_gate_envelope, i7);
    r2 = dm(SHK_GATE_OFF_gate_attq, i7);
    r3 = dm(SHK_GATE_OFF_gate_relq, i7);
    call _envq_fx;
    dm(SHK_GATE_OFF_gate_envelope, i7) = r0;

    /* threshold compare */
    r1 = pass r0;
    if le jump (pc, .gate_below_shkgate);   /* env==0: below */
#if DSP4_GATE_LINTHR
    r1 = dm(SHK_GATE_OFF_gate_thrq, i7);    /* 2^thr, Q4.28: compare linear */
    comp(r0, r1);
#else
    call _log2q_fx;
    r1 = dm(SHK_GATE_OFF_gate_thrq, i7);
    comp(r0, r1);
#endif
    if ge jump (pc, .gate_open_shkgate);
.gate_below_shkgate:
    r4 = dm(SHK_GATE_OFF_gate_hold_count, i7);
    r15 = 1;
    r4 = r4 - r15;
    dm(SHK_GATE_OFF_gate_hold_count, i7) = r4;
    if gt jump (pc, .gate_ramp_shkgate);
    r5 = dm(SHK_GATE_OFF_gate_rngq, i7);
    dm(SHK_GATE_OFF_gate_gain_target_q, i7) = r5;
    jump (pc, .gate_ramp_shkgate);
.gate_open_shkgate:
    r5 = 0x10000000;
    dm(SHK_GATE_OFF_gate_gain_target_q, i7) = r5;
    r4 = dm(SHK_GATE_OFF_gate_hold, i7);
    dm(SHK_GATE_OFF_gate_hold_count, i7) = r4;
.gate_ramp_shkgate:
    /* one-pole gain smoother (fixed): gain += a*(target-gain) */
    r0 = dm(SHK_GATE_OFF_gate_gain_target_q, i7);
    r1 = dm(SHK_GATE_OFF_gate_gain, i7);
    r2 = dm(SHK_GATE_OFF_gate_attq, i7);
    r3 = dm(SHK_GATE_OFF_gate_relq, i7);
    call _envq_fx;                 /* same one-pole form */
    dm(SHK_GATE_OFF_gate_gain, i7) = r0;

    r1 = r0;
    r0 = r13;
    mrf = r0 * r1 (ssi);
    call _mrf_rns28;
    dm(SHK_GATE_OFF_buf, i7) = r0;
    rts;
.gate_bypass_shkgate:
    dm(SHK_GATE_OFF_buf, i7) = r0;
    rts;
_shk_gate_blk.end:
#endif

/* ==== TUBE: one body for 32 strips ====
 * rewritten sites: 14 direct accesses, 0 DAG base loads, 0 address-to-register,
 * 2 predecessor-buffer accesses. */
#if (DSP4_SHARED_KERNELS & 2)
#define SHK_TUBE_OFF_tube_on         (0)
#define SHK_TUBE_OFF_tube_sat        (SHK_TUBE_OFF_tube_on + 1)
#define SHK_TUBE_OFF_tube_sat_target (SHK_TUBE_OFF_tube_sat + 1)
#define SHK_TUBE_OFF_tube_sat_step   (SHK_TUBE_OFF_tube_sat_target + 1)
#define SHK_TUBE_OFF_tube_sat_frames (SHK_TUBE_OFF_tube_sat_step + 1)
#define SHK_TUBE_OFF_buf             (SHK_TUBE_OFF_tube_sat_frames + 1)
#define SHK_TUBE_REC_LEN             (SHK_TUBE_OFF_buf + 1)

.section/pm seg_pmco;
.extern _mrf_rns28;
.global _shk_tube_blk;
_shk_tube_blk:

#if DSP4_BLOCK_KERNELS
    /* ---- per-block kernel ----
     * The saturation RAMP is per-sample by design (spi_handler
     * scales profile frame counts by 32 for ramps that decrement
     * once per sample), so `sat` -- and therefore sat_q -- changes
     * within the block while a ramp is running. Only the settled
     * case can hoist the conversion, so a ramping TUBE hands the
     * block to the per-sample body. A sat ramp is a transient. */

    r2 = dm(SHK_TUBE_OFF_tube_on, i7);
    r2 = pass r2;
    if eq jump (pc, .tkb_copy_shktube);
    r4 = dm(SHK_TUBE_OFF_tube_sat_frames, i7);
    r5 = 1;
    r4 = r4 - r5;
    if gt jump (pc, .tkb_ref_shktube);     /* ramping */

    f3 = dm(SHK_TUBE_OFF_tube_sat_target, i7);
    dm(SHK_TUBE_OFF_tube_sat, i7) = f3;
    r4 = 0x4D800000;
    f4 = r4;
    f3 = f3 * f4;
    r9 = fix f3;                          /* sat_q, hoisted */

    lcntr = DSP4_BLOCK_SIZE, do .tkb_lp_shktube until lce;
        r8 = dm(i3, 1);
        mrf = r8 * r8 (ssi);
        call _mrf_rns28;
        r10 = 0x10000000;
        r10 = r10 - r0;
        mrf = r9 * r10 (ssi);
        call _mrf_rns28;
        r10 = 0x10000000;
        r10 = r10 + r0;
        mrf = r8 * r10 (ssi);
        call _mrf_rns28;
        nop;
        nop;
    .tkb_lp_shktube: dm(i4, 1) = r0;
    rts;

.tkb_copy_shktube:
    lcntr = DSP4_BLOCK_SIZE, do .tkb_cp_shktube until lce;
        r0 = dm(i3, 1);
    .tkb_cp_shktube: dm(i4, 1) = r0;
    rts;

.tkb_ref_shktube:
    lcntr = DSP4_BLOCK_SIZE, do .tkb_rl_shktube until lce;
        r0 = dm(i3, 1);
        dm(i5, 0) = r0;
        call _shk_tube_smp;
        r0 = dm(SHK_TUBE_OFF_buf, i7);
    .tkb_rl_shktube: dm(i4, 1) = r0;
    rts;

.global _shk_tube_smp;
_shk_tube_smp:
#endif

    r0 = dm(i5, 0);

    r4 = dm(SHK_TUBE_OFF_tube_sat_frames, i7);
    r15 = 1;
    r4 = r4 - r15;
    if le jump (pc, .no_tramp_shktube);
    dm(SHK_TUBE_OFF_tube_sat_frames, i7) = r4;
    f3 = dm(SHK_TUBE_OFF_tube_sat, i7);
    f2 = dm(SHK_TUBE_OFF_tube_sat_step, i7);
    f3 = f3 + f2;
    dm(SHK_TUBE_OFF_tube_sat, i7) = f3;
    jump (pc, .tube_go_shktube);
.no_tramp_shktube:
    f3 = dm(SHK_TUBE_OFF_tube_sat_target, i7);
    dm(SHK_TUBE_OFF_tube_sat, i7) = f3;
.tube_go_shktube:

    r2 = dm(SHK_TUBE_OFF_tube_on, i7);
    r2 = pass r2;
    if eq jump (pc, .tube_bypass_shktube);

    r8 = r0;                      /* x */
    r4 = 0x4D800000;              /* sat -> Q4.28 */
    f4 = r4;
    f3 = f3 * f4;
    r9 = fix f3;                  /* sat_q */

    mrf = r8 * r8 (ssi);
    call _mrf_rns28;              /* r0 = x^2 */
    r10 = 0x10000000;             /* 1.0 Q4.28 */
    r10 = r10 - r0;               /* 1 - x^2 */
    mrf = r9 * r10 (ssi);
    call _mrf_rns28;              /* sat*(1-x^2) */
    r10 = 0x10000000;
    r10 = r10 + r0;               /* 1 + sat*(1-x^2) */
    mrf = r8 * r10 (ssi);
    call _mrf_rns28;              /* y */
    jump (pc, .tube_out_shktube);
